// CompareAssignment is the generated lifecycle comparison boundary. Pass stored snapshots and the effective assignment draft; its values are not transformed or compared to the result. Both snapshots, when present, must have the same primary key. This function performs no database work or automatic capture.
func CompareAssignment(before, after foundryvalue.Optional[Assignment], assigned AssignmentDraft) (AssignmentChanges, error) {
	before = foundryAssignmentSnapshot(before)
	after = foundryAssignmentSnapshot(after)
	var changes AssignmentChanges
	var err error
	changes.fields.ID, err = lifecycle.CompareModelField(codec.ID[Assignment](), before, after, assigned.fieldID.IsSet(), func(item Assignment) model.ID[Assignment] { return item.ID })
	if err != nil {
		return AssignmentChanges{}, fmt.Errorf("compare Assignment.ID: %w", err)
	}
	if before.IsSet() && after.IsSet() && (changes.fields.ID.Changed() || changes.fields.ID.Assigned()) {
		return AssignmentChanges{}, foundryfault.New(foundryfault.Invalid, "model change cannot replace or assign its existing primary key")
	}
	changes.fields.ProjectID, err = lifecycle.CompareModelField(codec.ID[Project](), before, after, assigned.fieldProjectID.IsSet(), func(item Assignment) model.ID[Project] { return item.ProjectID })
	if err != nil {
		return AssignmentChanges{}, fmt.Errorf("compare Assignment.ProjectID: %w", err)
	}
	changes.fields.PersonID, err = lifecycle.CompareModelField(codec.ID[Person](), before, after, assigned.fieldPersonID.IsSet(), func(item Assignment) model.ID[Person] { return item.PersonID })
	if err != nil {
		return AssignmentChanges{}, fmt.Errorf("compare Assignment.PersonID: %w", err)
	}
	changes.fields.Role, err = lifecycle.CompareModelField(codec.String[string](), before, after, assigned.fieldRole.IsSet(), func(item Assignment) string { return item.Role })
	if err != nil {
		return AssignmentChanges{}, fmt.Errorf("compare Assignment.Role: %w", err)
	}
	changes.before = before
	changes.after = after
	return changes, nil
}
func foundryAssignmentSnapshot(snapshot foundryvalue.Optional[Assignment]) foundryvalue.Optional[Assignment] {
	item, present := snapshot.Get()
	if !present {
		return foundryvalue.Optional[Assignment]{}
	}
	return foundryvalue.Set(Assignment{
		ID:        item.ID,
		ProjectID: item.ProjectID,
		PersonID:  item.PersonID,
		Role:      item.Role,
	})
}

