// AssignmentRetrievalHooks declares complete-model read callbacks. Reference a local factory with retrieval=Factory on the model directive. The stored model is a read-only value; getters remain explicit.
type AssignmentRetrievalHooks struct {
	// Retrieved runs after successful stored hydration and row closure. The executor retains the caller's capability and wrappers; no write transaction is created implicitly. Return an error to stop this read. Nil is skipped.
	Retrieved func(context.Context, database.Executor, Assignment) error
}

// AssignmentRetrievalObserver retains this model's concrete retrieval factory type. Names share the selected database's write/retrieval namespace.
type AssignmentRetrievalObserver = lifecycle.Observer[Assignment, AssignmentRetrievalHooks]

// NewAssignmentRetrievalObserver declares a typed retrieval observer without registering or constructing hooks.
func NewAssignmentRetrievalObserver(observer string) AssignmentRetrievalObserver {
	return lifecycle.NewRetrievalObserver[Assignment, AssignmentRetrievalHooks](observer)
}

// RegisterAssignmentRetrievalObserver binds dependency construction to a database module. Its factory runs once per nonempty complete fetch/batch and selected model role; write hydration, DTOs and scalar reads skip it.
func RegisterAssignmentRetrievalObserver(registrar *foundation.Registrar, pool foundation.Key[*database.DB], observer AssignmentRetrievalObserver, construct func(foundation.Resolver) (func() AssignmentRetrievalHooks, error)) error {
	return database.RegisterObserver(registrar, pool, observer, construct)
}
func (AssignmentRetrievalHooks) foundryRetrievalHooks(ctx context.Context, observerSet lifecycle.Observers) (foundryquery.RetrievalHooks[Assignment], error) {
	factories, err := lifecycle.RetrievalObserverFactories[Assignment, AssignmentRetrievalHooks](observerSet)
	if err != nil {
		return foundryquery.RetrievalHooks[Assignment]{}, err
	}
	var allHooks []AssignmentRetrievalHooks
	if err := ctx.Err(); err != nil {
		return foundryquery.RetrievalHooks[Assignment]{}, err
	}
	for _, factory := range factories {
		if err := ctx.Err(); err != nil {
			return foundryquery.RetrievalHooks[Assignment]{}, err
		}
		allHooks = append(allHooks, factory())
	}
	if err := ctx.Err(); err != nil {
		return foundryquery.RetrievalHooks[Assignment]{}, err
	}
	return foundryquery.RetrievalHooks[Assignment]{Retrieved: func(ctx context.Context, executor database.Executor, item Assignment) error {
		for _, hooks := range allHooks {
			if err := ctx.Err(); err != nil {
				return err
			}
			if hooks.Retrieved != nil {
				if err := hooks.Retrieved(ctx, executor, item); err != nil {
					return err
				}
			}
		}
		return ctx.Err()
	}}, nil
}

// AssignmentAuditPolicy selects stored fields for auditing. Zero applies automatic sensitive-name redaction.
// Exclusion/redaction cannot hide the primary key while retaining it as the subject identity; that policy fails capture.
type AssignmentAuditPolicy struct {
	_ [0]*Assignment
	// ID controls the audit representation of stored hook_assignments.id.
	ID record.Disclosure
	// ProjectID controls the audit representation of stored hook_assignments.project_id.
	ProjectID record.Disclosure
	// PersonID controls the audit representation of stored hook_assignments.person_id.
	PersonID record.Disclosure
	// Role controls the audit representation of stored hook_assignments.role.
	Role record.Disclosure
}

// Audit captures this operation's existing stored changes without getters, mutators or additional database work.
// Updates, soft deletes and restorations record assigned or changed fields plus the key; create and delete record every field.
// Standalone Compare results have no captured operation and cannot become lifecycle audit records.
func (changes AssignmentChanges) Audit(policy AssignmentAuditPolicy) (record.Model[Assignment, model.ID[Assignment]], error) {
	operation, present := changes.operation.Get()
	if !present {
		return record.Model[Assignment, model.ID[Assignment]]{}, foundryfault.New(foundryfault.Missing, "audit requires captured model changes")
	}
	item, present := changes.after.Get()
	if !present {
		item, present = changes.before.Get()
	}
	if !present {
		return record.Model[Assignment, model.ID[Assignment]]{}, foundryfault.New(foundryfault.Missing, "audit requires a stored model snapshot")
	}
	builder, err := record.NewBuilder(item.FoundryReference(), operation, "id", policy.ID)
	if err != nil {
		return record.Model[Assignment, model.ID[Assignment]]{}, err
	}
	if err = record.Capture(builder, "id", codec.ID[Assignment](), changes.fields.ID, policy.ID); err != nil {
		return record.Model[Assignment, model.ID[Assignment]]{}, err
	}
	if err = record.Capture(builder, "project_id", codec.ID[Project](), changes.fields.ProjectID, policy.ProjectID); err != nil {
		return record.Model[Assignment, model.ID[Assignment]]{}, err
	}
	if err = record.Capture(builder, "person_id", codec.ID[Person](), changes.fields.PersonID, policy.PersonID); err != nil {
		return record.Model[Assignment, model.ID[Assignment]]{}, err
	}
	if err = record.Capture(builder, "role", codec.String[string](), changes.fields.Role, policy.Role); err != nil {
		return record.Model[Assignment, model.ID[Assignment]]{}, err
	}
	return builder.Build()
}

