// AssignmentAuditing declares automatic auditing for normal lifecycle writes. Register it once through audit.Register.
// Existing observer registration owns dependency construction, duplicate detection and transaction lifetime.
func AssignmentAuditing(policy AssignmentAuditPolicy) record.Declaration {
	return record.Declare(func(registrar *foundation.Registrar, pool foundation.Key[*database.DB], resolve record.ResolveWriter) error {
		name, err := record.ObserverName[Assignment]()
		if err != nil {
			return err
		}
		return RegisterAssignmentObserver(registrar, pool, NewAssignmentObserver(name), func(resolver foundation.Resolver) (func() AssignmentHooks, error) {
			writer, err := resolve(resolver)
			if err != nil {
				return nil, err
			}
			if writer == nil {
				return nil, foundryfault.New(foundryfault.Invalid, "audit writer is not initialized")
			}
			return func() AssignmentHooks {
				write := func(ctx context.Context, tx *database.Tx, changes AssignmentChanges) error {
					captured, err := changes.Audit(policy)
					if err != nil {
						return err
					}
					return writer.RecordModel(ctx, tx, captured.Entry())
				}
				return AssignmentHooks{Created: write, Updated: write, Deleted: write, Restored: write}
			}, nil
		})
	})
}
